"""Real models: speech generated by the voice engine is detected and transcribed correctly."""

import re

import numpy as np
import pytest

from digital_me.stt import SileroVAD, SpeechDetector, SpeechEnded

pytestmark = pytest.mark.live


def words(text):
    return re.findall(r"[a-z']+", text.lower())


def word_accuracy(expected, heard):
    expected_words, heard_words = words(expected), set(words(heard))
    return sum(w in heard_words for w in expected_words) / len(expected_words)


@pytest.mark.parametrize(
    "sentence, voice",
    [
        ("What do you usually do on weekends?", "am_michael"),
        ("Can you tell me a little bit about your cat?", "bf_emma"),
        ("I was wondering whether you have ever been rock climbing outdoors.", "af_bella"),
    ],
)
def test_round_trip_speech_to_text(say, real_whisper, sentence, voice):
    heard = real_whisper.transcribe(say(sentence, voice)).text
    assert word_accuracy(sentence, heard) >= 0.9, heard


def test_silence_transcribes_to_nothing(real_whisper):
    assert real_whisper.transcribe(np.zeros(16_000 * 2, dtype=np.float32)).text == ""


def test_conversation_stream_is_cut_into_utterances_and_understood(say, real_whisper):
    silence = np.zeros(16_000, dtype=np.float32)
    stream = np.concatenate([silence, say("Hello there."), silence, say("How is your day going?"), silence])
    detector = SpeechDetector(SileroVAD())
    utterances = [e.audio for e in detector.feed(stream) if isinstance(e, SpeechEnded)]
    assert len(utterances) == 2
    texts = [real_whisper.transcribe(u).text.lower() for u in utterances]
    assert "hello" in texts[0]
    assert "day" in texts[1]
